TESTDATA["pet7-t3"] = {"title": "Cambridge PET 7 · Test 3", "format": "2010", "reading": [{"part": 1, "items": [{"n": 1, "text": "THIS DESK IS ONLY FOR THE COLLECTION OF BOOKED TICKETS", "img": "data:image/jpeg;base64,", "q": "", "options": ["You can buy a ticket at this desk to go straight into the theatre.", "You can book theatre tickets in advance at the collection desk.", "You can pick up theatre tickets here that you have already booked."], "answer": "C"}, {"n": 2, "text": "Bob,\nI tried to make you a dentist’s appointment for Friday but they don’t have one until Monday. If this is OK, ring them before 5 pm today.\nJill", "img": "data:image/jpeg;base64,", "q": "Bob needs to", "options": ["make a dentist’s appointment for Jill.", "phone the dentist about an appointment.", "tell Jill when he can go to the dentist."], "answer": "B"}, {"n": 3, "text": "IF YOUR SHOES ARE DIRTY, PLEASE REMOVE THEM BEFORE ENTERING THIS CHANGING ROOM", "img": "data:image/jpeg;base64,", "q": "", "options": ["You can keep your shoes on in the changing room unless they are dirty.", "Clean your shoes at the entrance to the changing room before you come in.", "All shoes must be taken off and left at the changing room entrance."], "answer": "A"}, {"n": 4, "text": "MESSAGE\nTony\nMaria’s sorry but she’s going to be late this evening. The train is delayed again! Don’t forget you’re meeting her at the station. She should be there at 7.15.\nAnita", "img": "data:image/jpeg;base64,", "q": "What is Anita doing?", "options": ["explaining that she will be late", "apologising for missing the meeting", "reminding somebody of an arrangement"], "answer": "C"}, {"n": 5, "text": "INTERNATIONAL STUDENTS’ CLUB\nNext Saturday’s coach trip is cancelled because of lack of interest", "img": "data:image/jpeg;base64,", "q": "", "options": ["To avoid us cancelling another Saturday trip, tell us what your interests are.", "Saturday’s coach trip is cancelled because there are transport problems.", "We are cancelling the trip on Saturday as numbers are too low."], "answer": "C"}]}, {"part": 2, "people": [{"n": 6, "name": "Susanna", "text": "Susanna only has a couple of hours free. She hates walking and would like to try something that brings her into contact with animals, although she is a bit nervous with them.", "answer": "E"}, {"n": 7, "name": "Kemal", "text": "Kemal is looking for some excitement and is keen to do something challenging. He also wants to get to know the area better. He can afford up to £50.", "answer": "G"}, {"n": 8, "name": "Frank and Sabine", "text": "Frank and Sabine want to go for a walk with their young family. They’d like to have lunch out but Sabine doesn’t like carrying things for the baby, or picnic things, around all day.", "answer": "C"}, {"n": 9, "name": "Charlotte", "text": "Charlotte is flying to the Brazilian rainforest soon to do some scientific research. She hopes to get some experience of living in the open air before she goes.", "answer": "D"}, {"n": 10, "name": "Tom", "text": "Tom wants to explore the natural beauty of the area in company with other people, doing something other than walking. He doesn’t have any equipment of his own but he has £40 to spend.", "answer": "B"}], "texts": [{"letter": "A", "title": "Windtek", "text": "Windtek runs windsurfing training courses for beginners, involving two three-hour private lessons (£89 with board and wetsuit hire). Experienced surfers can also practise on their own (£15 per hour). At this time of year, the water is still warm and an exciting day in the open air is promised!"}, {"letter": "B", "title": "Country Lanes", "text": "Based in a lovely forest, Country Lanes provides a relaxing experience for newcomers to cycling, experienced cyclists and those just looking for family fun. The one-day group tour (£30 per person) includes bike hire, route map and discounts on entry to tourist attractions."}, {"letter": "C", "title": "Llama Treks", "text": "For something different, let this company’s friendly South American animals accompany you on a walk through the hills. The llamas transport your bags while you enjoy the scenery. The most popular trip is a four-hour walk with a stop at a country restaurant (£55 per adult including meal – children free)."}, {"letter": "D", "title": "Survival School", "text": "If you’re thinking of taking a trip to somewhere far from cities and people, you might want to learn how to take care of yourself first. Survival School’s challenging weekend course (£150) will teach you fire-making, camp-building and recognising edible plants and wild animals. These skills could save your life."}, {"letter": "E", "title": "Park Stables", "text": "Have you ever thought of exploring a national park on horseback? Park Stables offers rides on horses specially chosen for their gentle characters. Beginners are welcome and riding hats and boots are provided free of charge. Private ride £25 per hour, family ride £42 per hour."}, {"letter": "F", "title": "Bygone Age", "text": "Practise a skill from the past! This company owns a 10-kilometre private railway track and offers train-lovers the opportunity to drive a steam train through pretty countryside. The return trip (£125) lasts one hour. There are picnic tables and a children’s playground at the station."}, {"letter": "G", "title": "Swallow Aviation", "text": "Get a bird’s-eye view of the countryside and see some of the region’s tourist sights from the air by taking a lesson in a two-seater microlight plane. It’s an adventure that’s not for the faint-hearted! The training plane is an Icarus C42 which flies at around 160 kph. Flights from £49."}, {"letter": "H", "title": "Island Link", "text": "This ferry company will take you to a beautiful, walker-friendly island. Some of its footpaths take in the coastline, while others pass through woods. You probably won’t see another walker all day! Walks vary in length from 2 to 8 hours. Ferry fare and walker’s guidebook £5."}]}, {"part": 3, "title": "Climbing mountains", "text": "Gertrude Benham was born in England in 1867. She had made 130 climbs in the European Alps before going to the Canadian Rocky Mountains in 1904, where she spent the summer climbing. In 1904, the paths of Gertrude Benham and Charles Fay briefly crossed. He had spent several successful summers climbing in the Rocky Mountains. In fact he was so successful that the Geographical Board of Canada asked him to select a mountain to take his name. He chose one known as Heejee and was determined to be the first to reach the top. But Gertrude Benham had the same idea.\n\nOn 19 July 1904, Gertrude and her guide, Christian Kaufmann, reached the top of a mountain which they thought was Heejee. Upon their return, however, they were told that that particular mountain was called something else. They decided to try again the next day but, unknown to Gertrude, Charles Fay and his guide Hans Kaufmann, Christian’s brother, were planning to climb Heejee that day as well.\n\nBoth groups set out on 20 July but Charles Fay and Hans Kaufmann found the snow conditions difficult and had to turn back. Gertrude and Christian were successful. Charles Fay was annoyed and later wrote in a letter, ‘Hans Kaufmann led me, against my wishes, up Consolation Valley instead of taking my advice to go round Moraine Lake, while Christian led Miss Benham straight to the top of the mountain.’\n\nSome people said that the Kaufmann brothers had wanted Gertrude to get to the top first and Hans had therefore taken Charles Fay on a route which took more time. Although this is a good story, no documents exist to prove this actually happened and it was never thought that Gertrude had any knowledge of it.\n\nDisappointed, Charles Fay asked if he could choose a different mountain to take his name and chose Mount Shappee, but then found out that Gertrude and Christian had climbed that one as well. At this point Charles Fay agreed to have his name attached to Heejee, as he had originally wanted. He finally climbed to its top on 5 August 1904. Half a century later, his grandson climbed the north-eastern side of the mountain, by then known as Mount Fay. No other climber had ever managed to do this.\n\nGertrude Benham then travelled to New Zealand and Japan to do more climbing before going home to England, spending time in Australia and India on the way. Charles Fay made many more successful climbs. The first hut built in the Canadian Rockies to shelter climbers was called the Fay Hut. It was built in 1927 but unfortunately was destroyed in a forest fire in 2003.", "items": [{"n": 11, "q": "Gertrude Benham had spent less time climbing in Canada than Charles Fay.", "answer": "A"}, {"n": 12, "q": "Charles Fay applied to an organisation to have a mountain named after him.", "answer": "B"}, {"n": 13, "q": "On 19 July, Gertrude Benham found out she had made a mistake.", "answer": "A"}, {"n": 14, "q": "Gertrude Benham decided to climb Mount Heejee with Charles Fay on 20 July.", "answer": "B"}, {"n": 15, "q": "Charles Fay blamed his guide when he failed to reach the top of Mount Heejee.", "answer": "A"}, {"n": 16, "q": "Gertrude Benham took a different route up Mount Heejee from Charles Fay.", "answer": "A"}, {"n": 17, "q": "Gertrude Benham knew Hans Kaufmann had a plan to choose a slow route up Mount Heejee.", "answer": "B"}, {"n": 18, "q": "The mountain which was named after Charles Fay was the one he had first chosen.", "answer": "A"}, {"n": 19, "q": "Charles Fay’s grandson followed a different route from his grandfather up Mount Fay.", "answer": "A"}, {"n": 20, "q": "The hut named after Charles Fay is still used by climbers.", "answer": "B"}]}, {"part": 4, "title": "At home in Venice", "text": "I was born in Venice, one of the most popular tourist destinations in Italy, and studied architecture at university here. Though I have also spent time away, I have always come back because it’s my home.\n\nIn Venice, there are no roads, only canals, so you have to get around on foot or by boat. I live on a canal in the Rialto area in a house that was built in 1588 for the Muti family, who were merchants in the silk trade. In the mid-eighteenth century, it was home to the Vezzi family, who made things like plates and bowls in fine china and became rich sending these around the world. These merchants’ houses in Venice are like palaces. Their owners had to have space to show off their goods, but the building also had to be an office, a factory, a store and a home. My house came into our family in 1919, when it was bought by my grandfather. He died before I was born but he was the director of a museum where I often do research on old documents. On some of these, I’ve seen notes in his handwriting, so, in a strange way, I met him through these documents.\n\nSadly, the population of Venice has dropped from 120,000 in the 1950s to about 60,000 now. This doesn’t include the thousands of tourists who come to visit. I welcome the tourists but unless something is done to stop everyday shops like bakeries and chemists from disappearing, the city will die. I want people who love the city to come here to live and work and give Venice back a life that is not just about tourism.", "items": [{"n": 21, "q": "What is the writer’s main reason for writing this text?", "options": ["to persuade more tourists to visit his city", "to give readers the history of his home town", "to say what he feels about his birthplace", "to describe some important moments in his life"], "answer": "C"}, {"n": 22, "q": "The family who first owned the writer’s home", "options": ["used to buy and sell silk.", "produced plates and bowls.", "were skilled architects.", "helped to build the canals."], "answer": "A"}, {"n": 23, "q": "What does the writer say about his grandfather?", "options": ["His grandfather taught him how to study documents.", "He didn’t find his grandfather’s handwriting easy to read.", "He wasn’t able to get to know his grandfather personally.", "His grandfather turned his home into a museum."], "answer": "C"}, {"n": 24, "q": "What is the writer’s attitude to Venice today?", "options": ["He hopes tourists will stop visiting the city.", "He would like people to get jobs working with tourists.", "He believes the city would benefit from having fewer inhabitants.", "He thinks local businesses should be encouraged to stay."], "answer": "D"}, {"n": 25, "q": "What might the writer say about his house?", "options": ["I have never lived anywhere else apart from in my home in the Rialto area of Venice.", "My house is on a canal in Venice and my family, starting with my grandfather, have lived there since 1919.", "We don’t know who lived in the house before 1588 but it was owned by merchants from then until the eighteenth century.", "The house was made bigger in the mid-eighteenth century because the owner wanted it to look like a palace."], "answer": "B"}]}, {"part": 5, "title": "Cave Paintings in Australia", "text": "A cave containing (0) ……… (over) 200 paintings was discovered in the Wollemi National Park, Australia, eight years ago. Some of the paintings are [26] least 3,000 years old. [27] is even more surprising is that the cave was found by chance by someone walking in the area. However, the site of the cave was so difficult to reach that it [28] a long time before researchers could visit it.\nThe exact location of the site has to be [29] secret. This is to [30] the cave from being visited by sightseers who do not [31] how easy it is to [32] the paintings.\nThe paintings show people and animals, [33] birds, lizards and other Australian animals that can [34] be seen today. According to researchers, [35] its recent discovery, nobody had visited the cave for around 200 years.", "gaps": {"26": {"options": ["in", "of", "to", "at"], "answer": "D"}, "27": {"options": ["How", "What", "Why", "Which"], "answer": "B"}, "28": {"options": ["lasted", "spent", "took", "finished"], "answer": "C"}, "29": {"options": ["remained", "set", "controlled", "kept"], "answer": "D"}, "30": {"options": ["prevent", "miss", "escape", "avoid"], "answer": "A"}, "31": {"options": ["catch", "realise", "dream", "feel"], "answer": "B"}, "32": {"options": ["waste", "injure", "damage", "upset"], "answer": "C"}, "33": {"options": ["involving", "adding", "including", "consisting"], "answer": "C"}, "34": {"options": ["yet", "already", "ever", "still"], "answer": "D"}, "35": {"options": ["by", "after", "until", "on"], "answer": "C"}}}], "writing": [{"part": 1, "title": "Here are some sentences about sailing. Complete the second sentence so that it means the same as the first, using no more than three words.", "items": [{"n": 1, "first": "My father was given his first boat by his parents.", "before": "My father’s parents", "after": "his first boat.", "answers": ["gave him", "gave my father"]}, {"n": 2, "first": "My father doesn’t have that boat any more.", "before": "My father", "after": "got that boat any more.", "answers": ["hasn't", "has not", "'s not"]}, {"n": 3, "first": "I wanted to start sailing, but my father insisted that I took some lessons first.", "before": "I wanted to start sailing, but my father said I had", "after": "some lessons first.", "answers": ["to take", "to have", "to get", "to do", "to attend", "better take", "better have", "better get", "better do", "better attend"]}, {"n": 4, "first": "My local sailing school said I was too young to join their courses.", "before": "My local sailing school said I wasn’t", "after": "to join their courses.", "answers": ["old enough"]}, {"n": 5, "first": "I found it more difficult to learn than I had expected.", "before": "It wasn’t", "after": "to learn as I had expected.", "answers": ["as easy", "so easy", "as simple", "so simple"]}]}, {"part": 2, "items": [{"n": 6, "kind": "message", "task": "You recently did a homework project about life in Britain, and your penfriend Judy helped you by sending some information.\n\nWrite an email to Judy. In your email, you should\n• thank her for her help\n• explain which information was most useful to you\n• say what your teacher thought about your project.\n\nWrite 35–45 words on your answer sheet.", "points": ["ringraziare per l'aiuto", "dire quale informazione è stata più utile", "dire che cosa ha detto l'insegnante del compito"]}]}, {"part": 3, "items": [{"n": 7, "kind": "letter", "task": "This is part of a letter you receive from your English friend, Sue.\n\n‘Tell me about TV in your country. Are the programmes interesting? How much TV do you watch? Do people watch too much TV these days?’\n\nNow write a letter to Sue, answering her questions.\nWrite your letter in about 100 words on your answer sheet."}, {"n": 8, "kind": "story", "task": "Your English teacher wants you to write a story.\nYour story must begin with this sentence:\n\nI looked in the shop window and I saw exactly what I wanted.\n\nWrite your story in about 100 words on your answer sheet."}]}], "listening": [{"part": 1, "audio": "audio/pet7-t3-l1.mp3", "items": [{"n": 1, "q": "Which present will the girl receive?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 2, "q": "Where will the tourists go last?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 3, "q": "How much does the man pay for the postage?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 4, "q": "Where in the theatre did the woman leave her gloves?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 5, "q": "Which dress does the woman like best?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 6, "q": "What’s the television programme about?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 7, "q": "Which vehicle does Steve intend to buy?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}]}, {"part": 2, "intro": "You will hear part of a radio interview with a woman called Linda Brown, who is talking about working in a cake shop when she was a student.", "audio": "audio/pet7-t3-l2.mp3", "items": [{"n": 8, "q": "Linda worked in a cake shop because", "options": ["her parents didn’t give her enough money.", "she wanted to give her parents some money.", "she needed to buy things for college."], "answer": "A"}, {"n": 9, "q": "Linda liked her first boss because he", "options": ["paid her well.", "was kind to her.", "sent her on a training course."], "answer": "B"}, {"n": 10, "q": "What did Linda enjoy about working in the shop?", "options": ["eating the cakes", "the smell of baking", "the clean workplace"], "answer": "B"}, {"n": 11, "q": "In the shop, Linda helped with", "options": ["baking bread.", "displaying cakes.", "making sandwiches."], "answer": "C"}, {"n": 12, "q": "Linda says that the full-time shop assistants", "options": ["were friendly to her.", "hadn’t got the same skills as her.", "didn’t work as hard as her."], "answer": "B"}, {"n": 13, "q": "What does Linda say about serving customers?", "options": ["She didn’t like dealing with complaints.", "She liked giving them advice.", "She enjoyed the busy part of the day."], "answer": "C"}]}, {"part": 3, "intro": "You will hear some recorded information about a museum.", "audio": "audio/pet7-t3-l3.mp3", "notes": "Central Museum\n\nThe museum gardens were first created in the year [14].\nThere are exhibitions of English furniture and [15] art.\nIn the museum shop, visitors can buy [16], cards and books.\nCars can be parked at the [17] near the museum.\nRegular buses to the museum leave from both the city centre and the [18].\nCall 451858 to find out more about [19] visits or room hire.", "answers": {"14": ["1921", "nineteen hundred and twenty one", "nineteen hundred twenty one", "nineteen and twenty one", "nineteen twenty one", "nineteen hundred and twenty-one", "nineteen hundred twenty-one", "nineteen and twenty-one", "nineteen twenty-one", "one thousand nine hundred and twenty one", "one thousand nine hundred and twenty-one"], "15": ["Japan", "Japanese"], "16": ["gifts", "gift"], "17": ["the hotel next door", "the hotel", "hotel next door", "hotel"], "18": ["the rail station", "the station", "rail station", "station", "the railway station", "railway station", "the train station", "train station"], "19": ["groups", "group"]}}, {"part": 4, "intro": "You will hear a conversation between a boy, Sam, and a girl, Carla, about a school concert.", "audio": "audio/pet7-t3-l4.mp3", "items": [{"n": 20, "q": "Carla is surprised that Mrs Ford wanted her to attend the meeting.", "answer": "B"}, {"n": 21, "q": "Sam says that last year’s concert was an improvement on earlier ones.", "answer": "A"}, {"n": 22, "q": "Carla enjoyed preparing for last year’s concert.", "answer": "B"}, {"n": 23, "q": "Sam tells Carla that she is the best pianist in the school.", "answer": "B"}, {"n": 24, "q": "Sam encourages Carla to accept Mrs Ford’s choice of music.", "answer": "B"}, {"n": 25, "q": "Sam realises that he must stop doing one of his activities.", "answer": "A"}]}]};
